import json,urllib.request,urllib.error,uuid,concurrent.futures,os
from pathlib import Path
T=os.environ['SUPABASE_ACCESS_TOKEN']
URL='https://api.supabase.com/v1/projects/oskccuajgbyabogbvedj/database/query'
def q(s):
 r=urllib.request.Request(URL,data=json.dumps({'query':s,'read_only':False}).encode(),headers={'Authorization':'Bearer '+T,'Content-Type':'application/json'})
 try:return True,json.load(urllib.request.urlopen(r,timeout=45))
 except urllib.error.HTTPError as e:return False,e.read().decode()
def good(s):
 ok,v=q(s)
 if not ok:raise AssertionError(v)
 return v
