 def gift(_):return q(f"BEGIN;SELECT set_config('request.jwt.claim.sub','{sender}',true);SELECT {schema}.xr_live_gift_send('testvideo11','rose','{uuid.uuid4()}');SELECT pg_sleep(0.2);COMMIT;")
